import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"A world exchanges only plain data with everything outside it","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"A world exchanges only plain data with everything outside it"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0011-a-world-exchanges-only-plain-data"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0011-a-world-exchanges-only-plain-data"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0011-a-world-exchanges-only-plain-data.md"}},"headers":[],"relativePath":"adr/0011-a-world-exchanges-only-plain-data.md","filePath":"adr/0011-a-world-exchanges-only-plain-data.md","lastUpdated":1794466182000}`),a={name:`adr/0011-a-world-exchanges-only-plain-data.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="a-world-exchanges-only-plain-data-with-everything-outside-it" tabindex="-1">A world exchanges only plain data with everything outside it <a class="header-anchor" href="#a-world-exchanges-only-plain-data-with-everything-outside-it" aria-label="Permalink to “A world exchanges only plain data with everything outside it”">​</a></h1><p>Status: accepted</p><p>Five rules keep a world&#39;s simulation separable from the code around it.</p><ol><li>Only ids and plain data cross a world&#39;s boundary. Nothing outside a world holds an entity object.</li><li>A world&#39;s state changes only through that world&#39;s own setters, on its own thread.</li><li>The simulation&#39;s output is a per-tick plain-data change log.</li><li>Offloaded work is a pure function of a plain-data snapshot, and its result returns as an input under <a href="/pr-preview/pr-2948/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>.</li><li>Movement between worlds is a message. A transfer carries the entity&#39;s saved form and leaves at a tick boundary of the source world. The destination admits it at the start of one of its own ticks, so the two worlds&#39; ticks do not need to align.</li></ol><p>Today handlers mutate player objects directly, and a handler can run between the awaits of a tick, so nothing marks where a world ends. With one writer per world and plain data at its edge, replication, pathfinding or a whole world can move to another thread later without changing the model. This program delivers the seams only. It moves no world, replication stage or pathfinding to another thread.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to “Considered options”">​</a></h2><p>The candidates for later are replication on workers, one thread per world, pathfinding offload and parallel regions inside a world. Parallel regions need typed-array storage and would reopen <a href="/pr-preview/pr-2948/adr/0007-one-entity-index-visible-on-write.html">ADR 0007</a> and <a href="/pr-preview/pr-2948/adr/0008-one-entity-model.html">ADR 0008</a>, so they come last. Pathfinding offload delivers a path a tick later than Java computes it and needs a parity check before it ships.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};